import React from "react";
import { useNavigate } from "react-router-dom";
import {
  FaJava,
  FaPython,
  FaDatabase,
  FaChartLine,
  FaLaptopCode
} from "react-icons/fa";

const Hero = () => {
  const navigate = useNavigate();

  return (
    <section className="hero">
      <div className="container">

        {/* LEFT SIDE */}
        <div className="left">
          <p className="tag">WELCOME</p>

          <h1>
            I'm <span className="name">Swetha A</span>
          </h1>

          <h2 className="role">
            Full Stack Developer • System Builder • UI Thinker
          </h2>

          <p className="desc">
            I design structured systems and build meaningful applications
            where logic, design, and performance work together.
          </p>

          <div className="buttons">
            <button className="btn primary" onClick={() => navigate("/projects")}>
              Explore Projects →
            </button>
            <button className="btn secondary" onClick={() => navigate("/about")}>
              About Me →
            </button>
          </div>
        </div>

        {/* RIGHT SIDE */}
        <div className="right">
          <div className="radar">

            {/* GLOW (REDUCED) */}
            <div className="glow"></div>

            {/* RINGS */}
            <div className="ring r1"></div>
            <div className="ring r2"></div>
            <div className="ring r3"></div>

            {/* SCAN */}
            <div className="sweep"></div>

            {/* CENTER GIRL WITH LAPTOP */}
            <div className="center">
              <img
                src="https://cdn-icons-png.flaticon.com/512/3893/3893079.png"
                alt="girl working on laptop"
              />
            </div>

            {/* ORBIT ICONS */}
            <div className="orbit o1"><FaJava /></div>
            <div className="orbit o2"><FaPython /></div>
            <div className="orbit o3"><FaDatabase /></div>
            <div className="orbit o4"><FaChartLine /></div>
            <div className="orbit o5"><FaLaptopCode /></div>

            {/* PARTICLES */}
            <span className="particle p1"></span>
            <span className="particle p2"></span>
            <span className="particle p3"></span>
            <span className="particle p4"></span>
            <span className="particle p5"></span>
            <span className="particle p6"></span>

          </div>
        </div>

      </div>

      <style>{`

        .hero {
          min-height: 100vh;
          display: flex;
          align-items: center;
          background: radial-gradient(circle at top, #0b1220, #050816);
          padding: 0 6%;
        }

        .container {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 40px;
          width: 100%;
          align-items: center;
        }

        /* LEFT */
        .tag {
          font-size: 12px;
          letter-spacing: 3px;
          color: #64748b;
        }

        h1 { font-size: 62px; }

        .name { color: #38BDF8; }

        .role { font-size: 20px; color: #94a3b8; }

        .desc {
          margin-top: 18px;
          color: #cbd5e1;
          max-width: 520px;
          line-height: 1.7;
        }

        .buttons {
          margin-top: 30px;
          display: flex;
          gap: 15px;
        }

        .btn {
          padding: 12px 22px;
          border-radius: 10px;
          border: 1px solid rgba(56,189,248,0.3);
          cursor: pointer;
        }

        .primary { background: #38BDF8; color: #0b1220; }
        .secondary { background: rgba(255,255,255,0.03); color: #38BDF8; }

        /* RADAR */
        .radar {
          position: relative;
          width: 380px;
          height: 380px;
          margin: auto;
        }

        /* REDUCED GLOW */
        .glow {
          position: absolute;
          width: 420px;
          height: 420px;
          top: -20px;
          left: -20px;
          background: radial-gradient(circle, rgba(56,189,248,0.12), transparent 70%);
          filter: blur(10px);
        }

        /* RINGS */
        .ring {
          position: absolute;
          border-radius: 50%;
          border: 1px solid rgba(56,189,248,0.15);
        }

        .r1 { width: 360px; height: 360px; top: 10px; left: 10px; }
        .r2 { width: 260px; height: 260px; top: 60px; left: 60px; }
        .r3 { width: 160px; height: 160px; top: 110px; left: 110px; }

        /* SCAN */
        .sweep {
          position: absolute;
          width: 180px;
          height: 180px;
          top: 100px;
          left: 100px;
          border-radius: 50%;
          background: conic-gradient(from 90deg, transparent, rgba(56,189,248,0.25), transparent);
          animation: rotate 4s linear infinite;
        }

        @keyframes rotate {
          100% { transform: rotate(360deg); }
        }

        /* CENTER GIRL */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%,-50%);
          z-index: 5;
        }

        .center img {
          width: 150px;
          filter: drop-shadow(0 0 10px rgba(56,189,248,0.25));
        }

        /* ORBIT */
        .orbit {
          position: absolute;
          top: 50%;
          left: 50%;
          width: 50px;
          height: 50px;

          display: flex;
          align-items: center;
          justify-content: center;

          font-size: 22px;
          border-radius: 50%;
          background: rgba(255,255,255,0.08);
          border: 1px solid rgba(56,189,248,0.4);
          box-shadow: 0 0 18px rgba(56,189,248,0.35);

          transform-origin: 0 0;
        }

        @keyframes orbit {
          0%   { transform: rotate(0deg) translate(170px) rotate(0deg); }
          100% { transform: rotate(360deg) translate(170px) rotate(-360deg); }
        }

        .o1 { animation: orbit 10s linear infinite; }
        .o2 { animation: orbit 12s linear infinite reverse; }
        .o3 { animation: orbit 9s linear infinite; }
        .o4 { animation: orbit 11s linear infinite reverse; }
        .o5 { animation: orbit 8s linear infinite; }

        /* PARTICLES */
        .particle {
          position: absolute;
          width: 6px;
          height: 6px;
          background: rgba(56,189,248,0.9);
          border-radius: 50%;
          box-shadow: 0 0 10px rgba(56,189,248,0.8);
          animation: float 6s infinite ease-in-out;
        }

        @keyframes float {
          0% { transform: translate(0,0); opacity: 0.3; }
          50% { transform: translate(10px,-10px); opacity: 1; }
          100% { transform: translate(0,0); opacity: 0.3; }
        }

        .p1 { top: 30px; left: 60px; animation-delay: 0s; }
        .p2 { top: 120px; right: 40px; animation-delay: 1s; }
        .p3 { bottom: 60px; left: 40px; animation-delay: 2s; }
        .p4 { bottom: 100px; right: 80px; animation-delay: 3s; }
        .p5 { top: 180px; left: 180px; animation-delay: 4s; }
        .p6 { top: 80px; right: 120px; animation-delay: 5s; }

      `}</style>

    </section>
  );
};

export default Hero;
